using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Feige.Core.Conversations;
using Feige.Core.Crypto;

namespace Feige.Core.Tests;

public sealed class V3WireTests
{
    // Snapshot of Transfer/main:开发文档/测试向量/v3.json, not generated by the C# implementation.
    private static JsonDocument Fixture() => JsonDocument.Parse(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures/v3.json")));

    [Fact]
    public void PublicVectors_TranscriptSignaturesAndDirectionalKeysMatch()
    {
        using var fixture = Fixture();
        var root = fixture.RootElement;
        var initiator = V3Wire.Decode<V3Offer>(Encoding.UTF8.GetBytes(root.GetProperty("initiatorOffer").GetRawText()));
        var responder = V3Wire.Decode<V3Offer>(Encoding.UTF8.GetBytes(root.GetProperty("responderOffer").GetRawText()));
        var transcript = V3Wire.Transcript(initiator, responder);
        Assert.Equal(Hex(root, "transcriptHex"), transcript);
        Assert.Equal(transcript, V3Wire.Transcript(responder, initiator));
        var digest = SHA256.HashData(transcript);
        Assert.Equal(Hex(root, "digestHex"), digest);
        foreach (var direction in new[] { "initiator", "responder" })
        {
            var offer = direction == "initiator" ? initiator : responder;
            Assert.True(IdentityKey.Verify(offer.IdentityPublicKeyDER, transcript,
                Convert.FromBase64String(root.GetProperty(direction + "ProofSignatureBase64").GetString()!)));
        }
        foreach (var (key, domain) in new[] { ("i2rHex", "initiator-to-responder"), ("r2iHex", "responder-to-initiator") })
            Assert.Equal(Hex(root, key), HKDF.DeriveKey(HashAlgorithmName.SHA256, Hex(root, "sharedHex"), 32, digest,
                Encoding.UTF8.GetBytes("feige-v3 " + domain)));
    }

    [Fact]
    public void PublicVectors_AllRecordsMatchInBothDirectionsWithoutSequenceReset()
    {
        using var fixture = Fixture(); var root = fixture.RootElement;
        foreach (var direction in new[] { "i2r", "r2i" })
        {
            using var sender = new V3RecordCipher(Hex(root, direction + "Hex"), Hex(root, "digestHex")[..4]);
            using var receiver = new V3RecordCipher(Hex(root, direction + "Hex"), Hex(root, "digestHex")[..4]);
            foreach (var record in root.GetProperty("records").EnumerateArray().Where(r => r.GetProperty("direction").GetString() == direction))
            {
                var type = record.GetProperty("type").GetByte(); var payload = Hex(record, "plaintextHex");
                var frame = sender.Seal(type, payload);
                Assert.Equal(Hex(record, "framedHex"), V3Wire.Length(frame.Length).Concat(frame));
                var opened = receiver.Open(frame);
                Assert.Equal(type, opened.Type);
                Assert.Equal(payload, opened.Payload);
                Assert.Equal(Hex(record, "aadHex"), frame[..13]);
            }
        }
    }

    [Fact]
    public void PublicVectors_UuidChunkAndDigestUseNetworkByteOrder()
    {
        using var fixture = Fixture(); var root = fixture.RootElement;
        var id = Guid.Parse("00112233-4455-6677-8899-AABBCCDDEEFF");
        byte[] bytes = new byte[16]; id.TryWriteBytes(bytes, bigEndian: true, out _);
        Assert.Equal(Hex(root, "uuidHex"), bytes);
        var chunk = root.GetProperty("records").EnumerateArray().Single(r => r.GetProperty("type").GetByte() == 3);
        var payload = Hex(chunk, "plaintextHex");
        Assert.Equal(id, new Guid(payload.AsSpan(0, 16), bigEndian: true));
        Assert.Equal(0UL, BinaryPrimitives.ReadUInt64BigEndian(payload.AsSpan(16, 8)));
        Assert.Equal(Hex(root, "fileSha256Hex"), SHA256.HashData(payload[24..]));
    }

    [Fact]
    public void Json_UsesExactV3PropertyNamesAndReceiptIsAString()
    {
        var id = Guid.NewGuid();
        using var json = JsonDocument.Parse(V3Wire.Encode(new V3File(id, "empty.txt", long.MaxValue)));
        Assert.Equal(id, json.RootElement.GetProperty("transferID").GetGuid());
        Assert.Equal(long.MaxValue, json.RootElement.GetProperty("size").GetInt64());
        Assert.False(json.RootElement.TryGetProperty("sha256", out _));
        using var receipt = JsonDocument.Parse(V3Wire.Encode(id));
        Assert.Equal(JsonValueKind.String, receipt.RootElement.ValueKind);
        Assert.Equal(id, receipt.RootElement.GetGuid());
    }

    [Theory]
    [InlineData("{}")]
    [InlineData("{\"id\":\"00112233-4455-6677-8899-aabbccddeeff\"}")]
    public void Text_RejectsMissingRequiredFields(string json)
        => Assert.Throws<JsonException>(() => V3Wire.Decode<V3Text>(Encoding.UTF8.GetBytes(json)));

    [Theory]
    [InlineData("")]
    [InlineData(" \r\n\t")]
    public void Text_RejectsWhitespace(string text)
        => Assert.Throws<InvalidDataException>(() => new V3Text(Guid.NewGuid(), text).Validate());

    [Fact]
    public void Text_ValidatesUtf8LengthAndPreservesUnicodeWhitespace()
    {
        new V3Text(Guid.NewGuid(), new string('a', 8192)).Validate();
        Assert.Throws<InvalidDataException>(() => new V3Text(Guid.NewGuid(), new string('你', 2731)).Validate());
        var message = new V3Text(Guid.NewGuid(), "  你好 👋\nWindows  ");
        message.Validate(); Assert.Equal(message, V3Wire.Decode<V3Text>(V3Wire.Encode(message)));
    }

    [Theory]
    [InlineData("../secret", "file", 1)]
    [InlineData("..", "file", 1)]
    [InlineData("a\\b", "file", 1)]
    [InlineData("a\nb", "file", 1)]
    [InlineData("file", "video", 1)]
    [InlineData("file", "file", -1)]
    public void File_RejectsInvalidMetadata(string name, string kind, long size)
        => Assert.ThrowsAny<Exception>(() => new V3File(Guid.NewGuid(), name, size, kind).Validate());

    [Fact]
    public void File_AllowsEmptyAndLargeFilesAndDefaultsKind()
    {
        foreach (long size in new[] { 0L, 101L * 1024 * 1024, long.MaxValue })
            new V3File(Guid.NewGuid(), "附件.txt", size).Validate();
        var json = Encoding.UTF8.GetBytes($"{{\"transferID\":\"{Guid.NewGuid()}\",\"fileName\":\"a\",\"size\":0}}");
        Assert.Equal("file", V3Wire.Decode<V3File>(json).Kind);
        Assert.Throws<JsonException>(() => V3Wire.Decode<V3File>("{}"u8.ToArray()));
    }

    [Theory]
    [InlineData(0)] [InlineData(5)] [InlineData(6)] [InlineData(11)]
    public void Cipher_RejectsUnknownAndReservedTypes(byte type)
    {
        using var cipher = new V3RecordCipher(new byte[32], new byte[4]);
        Assert.Throws<InvalidDataException>(() => cipher.Seal(type, [1]));
    }

    [Fact]
    public void Cipher_RejectsReplaySkipTamperingEmptyAndOversizedRecords()
    {
        using var sender = new V3RecordCipher(new byte[32], new byte[4]);
        using var receiver = new V3RecordCipher(new byte[32], new byte[4]);
        Assert.Throws<InvalidDataException>(() => sender.Seal(7, []));
        Assert.Throws<InvalidDataException>(() => sender.Seal(3, new byte[65537]));
        var first = sender.Seal(9, [1]); var second = sender.Seal(9, [2]);
        Assert.Throws<InvalidDataException>(() => receiver.Open(second));
        var tampered = first.ToArray(); tampered[^1] ^= 1;
        Assert.ThrowsAny<CryptographicException>(() => receiver.Open(tampered));
        Assert.Equal(new byte[] { 1 }, receiver.Open(first).Payload);
        Assert.Throws<InvalidDataException>(() => receiver.Open(first));
        Assert.Equal(new byte[] { 2 }, receiver.Open(second).Payload);
        Assert.Equal(65565, sender.Seal(3, new byte[65536]).Length);
    }

    [Fact]
    public void Offer_RejectsV1CodesSameRolesAndSelfIdentity()
    {
        using var fixture = Fixture();
        var offer = V3Wire.Decode<V3Offer>(Encoding.UTF8.GetBytes(fixture.RootElement.GetProperty("initiatorOffer").GetRawText()));
        Assert.Throws<InvalidDataException>(() => (offer with { Version = 1 }).Validate());
        Assert.Throws<InvalidDataException>(() => (offer with { SessionCode = "123456" }).Validate());
        Assert.Throws<InvalidDataException>(() => V3Wire.Transcript(offer, offer));
        Assert.Throws<InvalidDataException>(() => V3Wire.Transcript(offer, offer with { Role = 2 }));
    }

    private static byte[] Hex(JsonElement element, string name) => Convert.FromHexString(element.GetProperty(name).GetString()!);
}
